head.script:
scwin.onpageload = function() {
	var jsonData = [{
		"col1": "1111",
		"col2": "aaaa",
		"col3": "가가가가",
		"col4": "123"
	}, {
		"col1": "1111",
		"col2": "aaaa",
		"col3": "가가가가",
		"col4": "234"
	}, {
		"col1": "1111",
		"col2": "aaaa",
		"col3": "가가가가",
		"col4": "34"
	}, {
		"col1": "2222",
		"col2": "bbb",
		"col3": "가가가가",
		"col4": "546"
	}, {
		"col1": "2222",
		"col2": "bbb",
		"col3": "가가가가",
		"col4": "73"
	}, {
		"col1": "2222",
		"col2": "bbb",
		"col3": "가가가가",
		"col4": "732"
	}, {
		"col1": "333",
		"col2": "ccc",
		"col3": "가가가가",
		"col4": "we"
	}, {
		"col1": "333",
		"col2": "ccc",
		"col3": "가가가가",
		"col4": "1234"
	}, {
		"col1": "333",
		"col2": "ccc",
		"col3": "가가가가",
		"col4": "09"
	}, {
		"col1": "1111",
		"col2": "aaaa",
		"col3": "가가가가",
		"col4": "091"
	}, {
		"col1": "1111",
		"col2": "aaaa",
		"col3": "가가가가",
		"col4": "029"
	}];
	dataList1.setJSON(jsonData);
	var rowJSON = dataList1.getRowJSON(0);
	var j = [];
	for (var i = 0; i < 150; i++) {
		var tmp = {};
		for (var item in rowJSON) {
			if (item == "rowStatus") continue;
			if (item == "col1") tmp[item] = item + "_" + Math.floor(i / 3);
			if (item == "col2") tmp[item] = "a" + Math.floor(i / 3);
			if (item == "col3") tmp[item] = "가가가가";
			if (item == "col4") tmp[item] = (i + 1);
			if (item == "col5") tmp[item] = "나나나나" + (i + 1);
			if (item == "col6") tmp[item] = "d" + (i + 1);
			if (item == "col8" && ((i % 3) == 0 || (i % 5) == 0)) tmp[item] = "1";
		}
		j.push(tmp);
	}
	dataList1.setJSON(j);
};
